WITH src AS (
  SELECT * FROM jsonb_to_recordset($json$[{"id": "f3c24d3d-7e1e-5de1-ad3a-9e63337f0388", "email": "lina.bouaziz.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Matmata, village troglodyte", "description": "Village berbère aux maisons creusées dans le sol autour de cours circulaires, protégées de la chaleur et du froid. Décor repris dans Star Wars.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3a/Matmata.jpg/1280px-Matmata.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 33.5446, "longitude": 9.9686, "place_name": "Matmata", "region": "Gabès"}, {"id": "d0735797-1cef-5216-a5bc-fe3dc94184fe", "email": "sami.trabelsi.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Tamezret", "description": "Village berbère perché du Dahar, réputé pour son café des anciens et son architecture de pierre. Point de départ de randonnées dans la montagne.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1e/Tamezret.jpg/1280px-Tamezret.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 33.5419, "longitude": 9.8625, "place_name": "Tamezret", "region": "Gabès"}, {"id": "6b1109a1-9c43-5c31-b7fc-38c4997441b9", "email": "fakerben.noomen@gmail.com", "role": "eco_traveler", "type": "place", "title": "Chenini", "description": "Ksar berbère perché sur une crête, avec habitations troglodytes et mosquée souterraine. Joyau du Dahar.", "images": "https://upload.wikimedia.org/wikipedia/commons/3/38/Mosqu%C3%A9e_de_Chenini.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "latitude": 32.91, "longitude": 10.25, "place_name": "Chenini", "region": "Tataouine"}, {"id": "56547da7-9334-5a06-9590-20a50dd4dcde", "email": "lina.bouaziz.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Ghomrassen", "description": "Cité du Dahar connue comme la cité des pains, à l'entrée des villages de montagne du sud-est.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/Siege_de_municipalit%C3%A9_de_Ghomrassen.jpg/1280px-Siege_de_municipalit%C3%A9_de_Ghomrassen.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 33.05, "longitude": 10.33, "place_name": "Ghomrassen", "region": "Tataouine"}, {"id": "7c24f098-03ac-5f91-8f8e-55c9b99e91c0", "email": "sami.trabelsi.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Médina de Tunis", "description": "Médina classée à l'UNESCO, avec souks, palais et ruelles. Cœur historique de la capitale.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c1/Vue_de_Tunis.jpg/1280px-Vue_de_Tunis.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 36.7983, "longitude": 10.1706, "place_name": "Tunis", "region": "Tunis"}, {"id": "edbf7006-3124-5281-bec2-b2e555f4101d", "email": "fakerben.noomen@gmail.com", "role": "eco_traveler", "type": "place", "title": "Carthage, Thermes d'Antonin", "description": "Vestiges de la cité punique puis romaine, fondée par les Phéniciens. Les ruines sont dispersées dans la banlieue nord de Tunis.", "images": "https://upload.wikimedia.org/wikipedia/commons/1/1b/Carthage_sud_urbanisation.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "latitude": 36.8528, "longitude": 10.3306, "place_name": "Carthage", "region": "Tunis"}, {"id": "162d7851-2fce-5023-9686-073724a48e29", "email": "lina.bouaziz.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Sidi Bou Saïd", "description": "Village blanc et bleu dominant le golfe de Tunis. Célèbre pour son café des Délices et son architecture préservée.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Sidi_Chebaan.jpg/1280px-Sidi_Chebaan.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 36.87, "longitude": 10.3414, "place_name": "Sidi Bou Saïd", "region": "Tunis"}, {"id": "dab855b2-a069-50f8-83f6-5a363f956582", "email": "sami.trabelsi.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Hammamet, Dar Sébastian", "description": "Station balnéaire connue pour ses plages et la villa mauresque Dar Sébastian, devenue centre culturel international. Elle accueille le festival d'Hammamet.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/Hammamet_R01.jpg/1280px-Hammamet_R01.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 36.4, "longitude": 10.62, "place_name": "Hammamet", "region": "Nabeul"}, {"id": "55a1fb0c-7616-5ce4-8201-0482a0299bec", "email": "fakerben.noomen@gmail.com", "role": "eco_traveler", "type": "place", "title": "Médina de Sousse", "description": "Pôle culturel et économique de la côte est, avec une médina historique. À une vingtaine de kilomètres de Monastir.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b9/Sousse_Ribat_Aussicht.JPG/1280px-Sousse_Ribat_Aussicht.JPG?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 35.8256, "longitude": 10.6411, "place_name": "Sousse", "region": "Sousse"}, {"id": "3b22c873-dcbf-5440-8891-219c7316bef9", "email": "lina.bouaziz.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Ribat de Monastir", "description": "Ville côtière natale d'Habib Bourguiba, au cœur historique intéressant à visiter. Forme un noyau culturel avec Sousse.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/View_of_Monastir_from_the_ribat_tower.jpg/1280px-View_of_Monastir_from_the_ribat_tower.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 35.7772, "longitude": 10.8317, "place_name": "Monastir", "region": "Monastir"}, {"id": "2d2e8821-0815-5e94-864a-84cb9c779445", "email": "sami.trabelsi.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Médina de Mahdia", "description": "Port de pêche niché sur la presqu'île du Cap Africa, avec médina blanche. L'artisanat y est développé, notamment le tissage de la soie et de la laine.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2c/Mahdia_des_de_la_Torre_Obscura.jpg/1280px-Mahdia_des_de_la_Torre_Obscura.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 35.5047, "longitude": 11.0622, "place_name": "Mahdia", "region": "Mahdia"}, {"id": "9a3ebb26-2bb5-5e60-8280-a043bffc9923", "email": "fakerben.noomen@gmail.com", "role": "eco_traveler", "type": "place", "title": "Amphithéâtre d'El Jem", "description": "Troisième plus grand amphithéâtre romain après le Colisée et celui de Capoue. Il accueille chaque année un festival de musique symphonique.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ca/ElDjem.JPG/1280px-ElDjem.JPG?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 35.2964, "longitude": 10.7068, "place_name": "El Jem", "region": "Mahdia"}, {"id": "59f3c4f1-df06-5e78-bdc1-58eff69e23a3", "email": "lina.bouaziz.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Médina de Sfax", "description": "Médina de la deuxième ville du pays, port et centre économique. Aéroport international de Sfax.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/83/Sfax%2Cfa%C3%A7ades_de_l%E2%80%99immeuble.jpg/1280px-Sfax%2Cfa%C3%A7ades_de_l%E2%80%99immeuble.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 34.7406, "longitude": 10.7603, "place_name": "Sfax", "region": "Sfax"}, {"id": "a39501e0-daeb-5bff-855d-86ed6ef69fbd", "email": "sami.trabelsi.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Médina de Kairouan", "description": "Première ville sainte du Maghreb, médina classée à l'UNESCO. Grande Mosquée et mosquée des Trois Portes datent du IXe siècle.", "images": "https://upload.wikimedia.org/wikipedia/commons/b/b2/Great_Mosque_of_Kairouan_Panorama_-_Grande_Mosqu%C3%A9e_de_Kairouan_Panorama.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "latitude": 35.6781, "longitude": 10.0963, "place_name": "Kairouan", "region": "Kairouan"}, {"id": "45ebd6a9-e761-5abb-8325-62939229d1c8", "email": "fakerben.noomen@gmail.com", "role": "eco_traveler", "type": "place", "title": "Ruines de Dougga", "description": "Petite ville romaine parmi les mieux conservées d'Afrique du Nord, perchée sur une colline. Capitole, théâtre, thermes et temples y sont visibles.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/79/Dougga%2C_Beja.jpg/1280px-Dougga%2C_Beja.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 36.4233, "longitude": 9.2208, "place_name": "Dougga", "region": "Béja"}, {"id": "b04e0dad-5d36-5e9c-80c0-dc9c6b1cc3ee", "email": "lina.bouaziz.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Bulla Regia", "description": "Site archéologique romain du nord-ouest, connu pour ses maisons semi-enterrées.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Bulla_Regia_overall_plan.svg/1280px-Bulla_Regia_overall_plan.svg.png?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 36.5578, "longitude": 8.7556, "place_name": "Bulla Regia", "region": "Jendouba"}, {"id": "3d010e04-64e8-5939-8f30-c2e06620dfdb", "email": "sami.trabelsi.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Cascades de Beni M'Tir", "description": "Cascades naturelles dans la forêt de Kroumirie, accessibles par un sentier ombragé depuis le village.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/%C3%89glise_de_Beni_Mtir_1.jpg/1280px-%C3%89glise_de_Beni_Mtir_1.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 36.7223, "longitude": 8.7336, "place_name": "Beni M'Tir", "region": "Jendouba"}, {"id": "6c5a5dca-c1d1-5665-ac6a-ec714957e6b0", "email": "fakerben.noomen@gmail.com", "role": "eco_traveler", "type": "place", "title": "Tabarka, fort génois", "description": "Côte verdoyante de falaises et de forêts descendant jusqu'à la mer, dominée par un fort génois. Accueille un festival de jazz en août.", "images": "https://upload.wikimedia.org/wikipedia/commons/5/52/Port_tabarka.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "latitude": 36.96, "longitude": 8.75, "place_name": "Tabarka", "region": "Jendouba"}, {"id": "bc9492b8-17e4-5215-86e5-02fbb73b09fc", "email": "lina.bouaziz.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Vieux port de Bizerte", "description": "Ancien comptoir phénicien devenu port charmant, avec forteresse, casbah et médina. Réputé pour son poisson.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/Ksiba%2C_Bizerte_1.jpg/1280px-Ksiba%2C_Bizerte_1.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 37.2744, "longitude": 9.8739, "place_name": "Bizerte", "region": "Bizerte"}, {"id": "24467bcf-1c35-5e56-8b79-e24d297003ac", "email": "sami.trabelsi.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Parc national de l'Ichkeul", "description": "Lac alimenté par six oueds, refuge de centaines de milliers d'oiseaux migrateurs chaque hiver. Site ornithologique majeur.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/Parc_national_de_l%27Ichkeul27.jpg/1280px-Parc_national_de_l%27Ichkeul27.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 37.17, "longitude": 9.67, "place_name": "Ichkeul", "region": "Bizerte"}, {"id": "2bf041d0-f98f-5744-b958-c76e1b30725b", "email": "fakerben.noomen@gmail.com", "role": "eco_traveler", "type": "place", "title": "Le Kef, kasbah", "description": "Forteresse perchée vers 800 m sur la dorsale tunisienne, avec ruelles ottomanes et panoramas étendus.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ca/El_Kef%27s_casbah.jpg/1280px-El_Kef%27s_casbah.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 36.1742, "longitude": 8.7049, "place_name": "Le Kef", "region": "Le Kef"}, {"id": "0a5178a3-6d61-5178-b2ed-65f90e723450", "email": "lina.bouaziz.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Parc national de Boukornine", "description": "Parc situé à environ 18 km de Tunis, abritant plus de 25 espèces de mammifères.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9d/Boukornine_National_Park_001.jpg/1280px-Boukornine_National_Park_001.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 36.68, "longitude": 10.33, "place_name": "Boukornine", "region": "Ben Arous"}, {"id": "e49a9cf3-8e49-5764-82dd-c446511af138", "email": "sami.trabelsi.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Parc national d'El Feija", "description": "Parc frontalier avec l'Algérie, destiné à protéger le cerf de Berbérie, dans la région la plus humide du pays.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/TN-07.svg/1280px-TN-07.svg.png?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 36.5, "longitude": 8.3, "place_name": "El Feija", "region": "Jendouba"}, {"id": "6673c29c-9d39-549f-951c-aae0b99b0290", "email": "fakerben.noomen@gmail.com", "role": "eco_traveler", "type": "place", "title": "Temple des Eaux de Zaghouan", "description": "Site romain de Zaghouan, lié à l'aqueduc antique qui alimentait Carthage.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/TUNISIE_ZAGHOUAN_02.JPG/1280px-TUNISIE_ZAGHOUAN_02.JPG?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 36.4, "longitude": 10.14, "place_name": "Zaghouan", "region": "Zaghouan"}, {"id": "eec68876-f6dc-5ff8-93bc-d7c2c16c91a6", "email": "lina.bouaziz.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Oasis de Gafsa", "description": "Capitale du gouvernorat, porte du sud-ouest.", "images": "https://upload.wikimedia.org/wikipedia/commons/9/99/Gafsa.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "latitude": 34.425, "longitude": 8.784, "place_name": "Gafsa", "region": "Gafsa"}, {"id": "b26a387f-d358-550d-9eb1-33e17d966d5b", "email": "sami.trabelsi.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Metlaoui, Lézard rouge", "description": "Départ du train touristique Metlaoui–Redeyef à travers les gorges.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/Metlaoui_2020_06.jpg/1280px-Metlaoui_2020_06.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 34.3167, "longitude": 8.4, "place_name": "Metlaoui", "region": "Gafsa"}, {"id": "a1a489e1-2938-561e-afc3-195c5d3d3383", "email": "fakerben.noomen@gmail.com", "role": "eco_traveler", "type": "place", "title": "Palmeraie de Tozeur", "description": "Palmeraie de 400 000 dattiers, découverte à vélo ou en calèche. Médina en briques ocre et décors de Star Wars aux alentours.", "images": "https://upload.wikimedia.org/wikipedia/commons/e/ea/Tozeur_sud_tunisien.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "latitude": 33.9197, "longitude": 8.1335, "place_name": "Tozeur", "region": "Tozeur"}, {"id": "15c3e39a-892b-58d6-a7da-43acd69cc1f1", "email": "lina.bouaziz.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Cascades de Chebika", "description": "Oasis de montagne avec cascades, dans le Jérid. Étape des excursions depuis Tozeur.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a8/Abandoned_and_New_Village_of_Chebika.jpg/1280px-Abandoned_and_New_Village_of_Chebika.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 34.3167, "longitude": 7.95, "place_name": "Chebika", "region": "Tozeur"}, {"id": "2b1a9eda-7930-5d98-a939-36ac13ca7378", "email": "sami.trabelsi.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Tamerza", "description": "Oasis abandonnée après une inondation, devenue un espace naturel. On remonte le canyon jusqu'à une grande cascade.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/Oasis_de_Tamerza.JPG/1280px-Oasis_de_Tamerza.JPG?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 34.3833, "longitude": 7.9333, "place_name": "Tamerza", "region": "Tozeur"}, {"id": "6d7d7605-9497-5b47-a1ed-9a0c4dbb992a", "email": "fakerben.noomen@gmail.com", "role": "eco_traveler", "type": "place", "title": "Chott el-Jérid", "description": "Immense plaine saline et lac de sel entre Tozeur et Kébili.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a9/Barque_sur_une_mer_de_sel_%C3%A0_Chott_Jrid.jpg/1280px-Barque_sur_une_mer_de_sel_%C3%A0_Chott_Jrid.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 33.7, "longitude": 8.4, "place_name": "Chott el-Jérid", "region": "Tozeur"}, {"id": "3bc53342-0d24-5696-91bb-6ab78b504319", "email": "lina.bouaziz.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Douz, porte du Sahara", "description": "Ancienne étape caravanière ouvrant sur le Grand Erg. Le coucher de soleil sur les dunes y est un moment privilégié.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/97/Douz_downtown_01.JPG/1280px-Douz_downtown_01.JPG?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 33.4569, "longitude": 9.0214, "place_name": "Douz", "region": "Kébili"}, {"id": "23e6a4bf-6010-5559-8e16-966f5e1853be", "email": "sami.trabelsi.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Ksar Ghilane", "description": "Oasis aux sources chaudes en bordure du Grand Erg oriental, étape de méharées en bivouac.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/63/Kleinkastell_Tisavar_-_Ksar_Ghilane%2C_S%C3%BCdtunesien.svg/1280px-Kleinkastell_Tisavar_-_Ksar_Ghilane%2C_S%C3%BCdtunesien.svg.png?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 32.99, "longitude": 9.63, "place_name": "Ksar Ghilane", "region": "Tataouine"}, {"id": "5365909a-d689-529e-981e-77d749165ea4", "email": "fakerben.noomen@gmail.com", "role": "eco_traveler", "type": "place", "title": "Oasis de Gabès", "description": "Oasis maritime de Gabès, point de départ vers Matmata et le Dahar.", "images": "https://upload.wikimedia.org/wikipedia/commons/7/7c/Palmeraie_gab%C3%A8s2.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "latitude": 33.8881, "longitude": 10.0975, "place_name": "Gabès", "region": "Gabès"}, {"id": "7158a295-d575-5d80-9aef-d26eda71c958", "email": "lina.bouaziz.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Houmt Souk, Djerba", "description": "Marché réunissant des pièces d'artisanat de tout le pays, principal bourg de l'île de Djerba.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/18/Fort_Djerba_Tunisia.jpg/1280px-Fort_Djerba_Tunisia.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 33.8756, "longitude": 10.8575, "place_name": "Houmt Souk", "region": "Médenine"}, {"id": "55ec83ca-550c-5ed6-89af-5f3467c7e222", "email": "sami.trabelsi.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Synagogue de la Ghriba", "description": "Synagogue célèbre de l'île de Djerba, lieu de pèlerinage.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8b/Djerba_Er_Riadh_Street_Art_19.JPG/1280px-Djerba_Er_Riadh_Street_Art_19.JPG?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 33.8153, "longitude": 10.8572, "place_name": "Erriadh", "region": "Médenine"}, {"id": "e1b14f07-b350-5943-8d03-bcc4852a3933", "email": "fakerben.noomen@gmail.com", "role": "eco_traveler", "type": "place", "title": "Djerbahood, Erriadh", "description": "Village d'Erriadh transformé en musée de street art à ciel ouvert.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8b/Djerba_Er_Riadh_Street_Art_19.JPG/1280px-Djerba_Er_Riadh_Street_Art_19.JPG?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 33.81, "longitude": 10.86, "place_name": "Erriadh", "region": "Médenine"}, {"id": "fd55c368-9542-5b35-8fd8-12e43679186d", "email": "lina.bouaziz.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Guellala, village de potiers", "description": "Village de potiers de Djerba, avec ateliers de poterie ouverts aux visiteurs.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/Guellala.jpg/1280px-Guellala.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 33.73, "longitude": 10.88, "place_name": "Guellala", "region": "Médenine"}, {"id": "575ddae3-685d-5215-8977-cd8643a43b80", "email": "sami.trabelsi.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Zarzis", "description": "Ville côtière du sud-est, étape entre Djerba et la frontière libyenne.", "images": "https://upload.wikimedia.org/wikipedia/commons/1/19/Tunesien_Zarzis_2.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "latitude": 33.5039, "longitude": 11.1122, "place_name": "Zarzis", "region": "Médenine"}, {"id": "0c4bdac8-edfd-5ea4-897c-ce421754dcda", "email": "fakerben.noomen@gmail.com", "role": "eco_traveler", "type": "place", "title": "Tataouine, ksour et décors Star Wars", "description": "Ville du sud près de la frontière libyenne, base pour visiter les ksour, anciens greniers fortifiés. Ces lieux ont servi de décor à Star Wars.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/Tataouine_by_night.jpg/1280px-Tataouine_by_night.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 32.9297, "longitude": 10.4518, "place_name": "Tataouine", "region": "Tataouine"}, {"id": "f6d2830b-d4c9-5925-9101-c99ed290337e", "email": "lina.bouaziz.tn@gmail.com", "role": "eco_traveler", "type": "place", "title": "Nabeul", "description": "Capitale du Cap Bon, ville d'artisanat et de poterie.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/Sculpture_oranges_Nabeul.jpg/1280px-Sculpture_oranges_Nabeul.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 36.4513, "longitude": 10.7358, "place_name": "Nabeul", "region": "Nabeul"}, {"id": "64e68967-2a7f-577d-9760-6b7c6da4f781", "email": "lina.bouaziz.tn@gmail.com", "role": "eco_traveler", "type": "experience", "title": "Festival international du Sahara de Douz", "description": "56e édition du 12 au 15 novembre 2026 : courses de dromadaires, mariages traditionnels, poésie bédouine et fantasia. Se tient dans les dunes de Ouled Debbab.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/97/Douz_downtown_01.JPG/1280px-Douz_downtown_01.JPG?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 33.4569, "longitude": 9.0214, "place_name": "Douz", "region": "Kébili"}, {"id": "2184726a-a507-5aa5-baa4-d8ee7ed88365", "email": "sami.trabelsi.tn@gmail.com", "role": "eco_traveler", "type": "experience", "title": "Festival des Oasis de Tozeur", "description": "Rendez-vous de fin décembre, pendant la récolte des dattes : animations de rue, défilés, spectacles folkloriques et courses de chevaux. Dates exactes de l'édition à confirmer.", "images": "https://upload.wikimedia.org/wikipedia/commons/e/ea/Tozeur_sud_tunisien.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "latitude": 33.9197, "longitude": 8.1335, "place_name": "Tozeur", "region": "Tozeur"}, {"id": "f6ef8d06-2c72-50d3-9708-d065b6424a49", "email": "fakerben.noomen@gmail.com", "role": "eco_traveler", "type": "experience", "title": "Festival international de Carthage", "description": "Événement culturel le plus connu du pays, dans le théâtre antique, avec concerts de juillet à août. Dates de la prochaine édition à confirmer.", "images": "https://upload.wikimedia.org/wikipedia/commons/1/1b/Carthage_sud_urbanisation.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "latitude": 36.8528, "longitude": 10.3306, "place_name": "Carthage", "region": "Tunis"}, {"id": "ba9944cb-2f21-5444-954a-269137dcc4ef", "email": "lina.bouaziz.tn@gmail.com", "role": "eco_traveler", "type": "experience", "title": "Festival international d'Hammamet", "description": "Se tient chaque année en juillet et août dans un amphithéâtre face à la mer, dans les jardins de Dar Sébastian. Programmation variée sous l'égide du ministère de la Culture.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/de/Tunisie_Festival_international_Hammamet.jpg/1280px-Tunisie_Festival_international_Hammamet.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 36.4, "longitude": 10.62, "place_name": "Hammamet", "region": "Nabeul"}, {"id": "3f6d5ad6-1fbd-5101-b368-36bf09a3593c", "email": "sami.trabelsi.tn@gmail.com", "role": "eco_traveler", "type": "experience", "title": "Carnaval de Yasmine Hammamet", "description": "Défilé de fin mars qui anime le front de mer le temps d'un week-end. Dates de la prochaine édition à confirmer.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e1/2007-11-21-Yasmine-Hammamet-8.JPG/1280px-2007-11-21-Yasmine-Hammamet-8.JPG?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 36.37, "longitude": 10.55, "place_name": "Hammamet", "region": "Nabeul"}, {"id": "ef0d8a28-0c7c-59a6-82c8-7281032cb047", "email": "fakerben.noomen@gmail.com", "role": "eco_traveler", "type": "experience", "title": "Tabarka Jazz Festival", "description": "Concerts de jazz en plein air dans la ville côtière de Tabarka, au mois d'août. Dates de la prochaine édition à confirmer.", "images": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d4/Tabarka%2C_d%C3%A9cembre_2014_%2825%29.jpg/1280px-Tabarka%2C_d%C3%A9cembre_2014_%2825%29.jpg?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail", "latitude": 36.96, "longitude": 8.75, "place_name": "Tabarka", "region": "Jendouba"}, {"id": "f29f359e-0647-516b-b092-d2f75f53009d", "email": "lina.bouaziz.tn@gmail.com", "role": "eco_traveler", "type": "experience", "title": "Festival international de musique symphonique d'El Jem", "description": "Musique classique avec orchestres nationaux et étrangers dans l'amphithéâtre romain, chaque année en août. Dates de la prochaine édition à confirmer.", "images": "https://upload.wikimedia.org/wikipedia/commons/2/25/Festival_el_jem.JPG?utm_source=fr.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled", "latitude": 35.2964, "longitude": 10.7068, "place_name": "El Jem", "region": "Mahdia"}]$json$::jsonb) AS x(
    id uuid, email text, role text, type text, title text, description text,
    images text, latitude numeric, longitude numeric, place_name text, region text
  )
), resolus AS (
  SELECT s.*, COALESCE(
    (SELECT id FROM users WHERE email = s.email),
    (SELECT id FROM users WHERE role = s.role::users_role_enum ORDER BY created_at LIMIT 1)
  ) AS author_id
  FROM src s
)
INSERT INTO publications
  (id, author_id, type, title, description, images, latitude, longitude, place_name, region, status)
SELECT id, author_id, type, title, description, NULLIF(images, ''), latitude, longitude, place_name, region, 'approved'
FROM resolus WHERE author_id IS NOT NULL
ON CONFLICT (id) DO NOTHING;

