    id uuid, email text, role text, title text, description text, price numeric,
    duration text, offer_type text, offer_subtype text, confirmation_mode text,
    price_type text, capacity int, deposit_percentage int, images jsonb,
    inclusions text, region text, meeting_point text, meeting_lat numeric,
    meeting_lng numeric, cancellation_policy text, offer_mode text
  )
), resolus AS (
  SELECT s.*, COALESCE(
    (SELECT id FROM users WHERE email = s.email),
    (SELECT id FROM users WHERE role = s.role::users_role_enum ORDER BY created_at LIMIT 1)
  ) AS author_id
  FROM src s
)
INSERT INTO offers
  (id, author_id, author_type, title, description, price, duration, offer_type,
   offer_subtype, confirmation_mode, price_type, capacity, deposit_percentage,
   images, inclusions, region, meeting_point, meeting_lat, meeting_lng,
   cancellation_policy, offer_mode, status)
SELECT id, author_id, 'provider', title, description, price, duration, offer_type,
       offer_subtype, confirmation_mode, price_type, capacity, deposit_percentage,
       images::text, inclusions, region, meeting_point, meeting_lat, meeting_lng,
       cancellation_policy, offer_mode, 'approved'
FROM resolus WHERE author_id IS NOT NULL
ON CONFLICT (id) DO NOTHING;

