)
INSERT INTO publication_likes (id, publication_id, user_id, user_role)
SELECT s.id, s.publication_id, u.id, s.role
FROM src s JOIN users u ON u.email = s.email
ON CONFLICT DO NOTHING;

-- ═══════════════════════════════════════════════════════════════════════
-- Vérification
-- ═══════════════════════════════════════════════════════════════════════
COMMIT;

SELECT 'lieux' AS entite, count(*) FROM publications WHERE type='place' AND status='approved'
UNION ALL SELECT 'evenements', count(*) FROM publications WHERE type='experience' AND status='approved'
UNION ALL SELECT 'circuits', count(*) FROM circuits WHERE status='approved'
UNION ALL SELECT 'hebergements', count(*) FROM offers WHERE offer_type='hebergement' AND status='approved'
UNION ALL SELECT 'likes', count(*) FROM publication_likes
ORDER BY entite;
